class InvariantViolationError(Exception):
    """Raised when data invariants are violated."""
    pass


class HighRiskModule20:
    """Distributed Consistency domain module for high-risk operations."""

    def validate_invariant(self, payload: dict) -> bool:
        """
        Enforces that the payload has a 'valid' key set to True.
        Raises InvariantViolationError otherwise and returns True on success.
        """
        if not isinstance(payload, dict) or payload.get("valid") is not True:
            raise InvariantViolationError("Payload invariant validation failed: 'valid' must be True.")
        return True
